import sys

# Increase recursion depth for deep trees
sys.setrecursionlimit(200000)

def solution(input_data):
    input_lines = input_data.strip().split('\n')
    n, m = map(int, input_lines[0].split())

    if m == n - 1:
        return ""

    edges = []
    for i in range(m):
        a, b, e = map(int, input_lines[i + 1].split())
        edges.append((a, b, e, i))

    # Sort edges by weight for Kruskal's
    edges_sorted = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Kruskal's to find MST
    mst_edges = []
    mst_count = 0
    mst_set = set()

    for a, b, e, idx in edges_sorted:
        if union(a, b):
            mst_edges.append((a, b, e))
            mst_set.add((min(a, b), max(a, b)))
            mst_count += 1
            if mst_count == n - 1:
                break

    # Build tree adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b, e in mst_edges:
        adj[a].append((b, e))
        adj[b].append((a, e))

    # DFS to compute depth, parent, and max_weight to root
    depth = [0] * (n + 1)
    up = [[0] * 20 for _ in range(n + 1)]  # binary lifting table
    mw = [[0] * 20 for _ in range(n + 1)]  # max weight to ancestor

    visited = [False] * (n + 1)

    def dfs(u, p, w):
        visited[u] = True
        depth[u] = depth[p] + 1 if p != 0 else 0
        up[u][0] = p
        mw[u][0] = w

        for i in range(1, 20):
            if up[u][i-1] != 0:
                up[u][i] = up[up[u][i-1]][i-1]
                mw[u][i] = max(mw[u][i-1], mw[up[u][i-1]][i-1])
            else:
                up[u][i] = up[u][i-1] if up[u][i-1] != 0 else 0
                mw[u][i] = mw[u][i-1]

        for v, w_edge in adj[u]:
            if not visited[v] or v != p:
                dfs(v, u, w_edge)

    dfs(1, 0, 0)

    def get_max(u, v):
        # Similar to LCA, find max on path
        max_w = 0
        if depth[u] < depth[v]:
            u, v = v, u

        # Move u up to same depth as v
        for i in range(19, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                max_w = max(max_w, mw[u][i])
                u = up[u][i]

        if u == v:
            return max_w

        # Move both up until they meet
        for i in range(19, -1, -1):
            if up[u][i] != up[v][i]:
                max_w = max(max_w, mw[u][i], mw[v][i])
                u = up[u][i]
                v = up[v][i]

        max_w = max(max_w, mw[u][0], mw[v][0])
        return max_w

    # For each non-MST edge, compute E_max = max weight on path in MST
    results = []

    for a, b, e, idx in edges:
        if (min(a, b), max(a, b)) in mst_set:
            continue

        max_on_path = get_max(a, b)
        results.append(str(max_on_path))

    return '\n'.join(results)

