MOD = 1000000007

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Find empty positions (indices with -1, 1-indexed)
    empty_positions = []
    for i in range(n):
        if arr[i] == -1:
            empty_positions.append(i + 1)

    # Find missing values
    present_values = set()
    for x in arr:
        if x != -1:
            present_values.add(x)
    missing_values = set()
    for i in range(1, n + 1):
        if i not in present_values:
            missing_values.add(i)

    m = len(empty_positions)  # Should equal len(missing_values)

    # Count k: number of positions i where position i is empty AND value i is missing
    k = 0
    for i in empty_positions:
        if i in missing_values:
            k += 1

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(2, m + 1):
        fact[i] = (fact[i-1] * i) % MOD

    def comb(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * pow(fact[r] * fact[n - r] % MOD, MOD - 2, MOD) % MOD

    # Inclusion-exclusion principle:
    # Sum_{r=0}^{k} (-1)^r * C(k, r) * (m-r)!
    result = 0
    for r in range(k + 1):
        ways = comb(k, r) * fact[m - r] % MOD
        if r % 2 == 1:
            result = (result - ways + MOD) % MOD
        else:
            result = (result + ways) % MOD

    return str(result) + '\n'

