from typing import List

class SegmentTree:
    def __init__(self, n):
        # 1 = free, 0 = occupied
        self.tree = [1] * (4 * (n + 1))

    def query(self, node, start, end, l, r):
        """Check if all days in [l, r] are free (return 1 if free, 0 if any occupied)"""
        if r < start or end < l:
            return 1
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        return min(
            self.query(2 * node, start, mid, l, r),
            self.query(2 * node + 1, mid + 1, end, l, r)
        )

    def update_range(self, node, start, end, l, r):
        """Mark days in [l, r] as occupied"""
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] = 0
            return
        mid = (start + end) // 2
        self.update_range(2 * node, start, mid, l, r)
        self.update_range(2 * node + 1, mid + 1, end, l, r)
        self.tree[node] = min(self.tree[2 * node], self.tree[2 * node + 1])

    def is_fully_free(self, l, r):
        """Check if range [l, r] is completely unoccupied"""
        return self.query(1, 1, self.n, l, r) == 1

