    for x in range(1, n + 1):
        day_count = 0
        for l, r in offers:
            # Offer must have sufficient length
            if r - l + 1 >= x:
                # Check if entire range is unoccupied
                if tree.is_fully_free(l, r):
                    tree.update_range(1, 1, n, l, r)
                    day_count += (r - l + 1)
        results.append(str(day_count))

    return '\n'.join(results) + '\n'

