    def get_prime_counts(nums):
        prime_counts = {}
        for i, num in enumerate(nums):
            d = 2
            while d * d <= num:
                if num % d == 0:
                    cnt = 0
                    while num % d == 0:
                        cnt += 1
                        num //= d
                    if d not in prime_counts:
                        prime_counts[d] = [0] * len(nums)
                    prime_counts[d][i] += cnt
                d += 1
            if num > 1:
                if num not in prime_counts:
                    prime_counts[num] = [0] * len(nums)
                prime_counts[num][i] += 1
        return prime_counts

    def dinic_max_flow(num_nodes, graph, s, t):
        total_flow = 0
