            return sphere_from_four(points_subset[0], points_subset[1], points_subset[2], points_subset[3])

    def sphere_from_two(p1, p2):
        c = ((p1[0] + p2[0]) / 2.0, 
             (p1[1] + p2[1]) / 2.0, 
             (p1[2] + p2[2]) / 2.0)
        return (c, distance(c, p1))

    def sphere_from_three(p1, p2, p3):
        center = circumcenter_2d(p1, p2, p3)
        if center is None:
            return (p1, 0.0)
