    m = len(s2)
    v = len(virus)

    # Edge case: if virus is empty or empty strings
    if v == 0 or n == 0 or m == 0:
        return "0"

    # Build KMP failure function for the virus
    pi = [0] * v
    for i in range(1, v):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Build transition table: trans[state][char] = next_state
    trans = [[0] * 26 for _ in range(v + 1)]
    for state in range(v + 1):
        for c in range(26):
            letter = chr(ord('A') + c)
            if state == v:
                trans[state][c] = 0  # If we matched full virus, reset to 0
                continue

            next_state = state
            while next_state > 0 and letter != virus[next_state]:
                next_state = pi[next_state - 1]

            if letter == virus[next_state]:
                next_state += 1
                if next_state == v + 1:
                    next_state = v  # Cap at v, not v+1
                elif next_state > v:
                    next_state = 0
            trans[state][c] = next_state

    # DP state: dp[i][j][k] = length of valid LCS using first i of s1, j of s2
    dp = [[[0] * (v + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    # Reuse dp to mark visited states: dp[i][j][k] uses value, -1 means unvisited
    dp[0][0][0] = -1  # Mark states as computed

    # Use another table for DP values, and parent for reconstruction
    dp_vals = [[[0] * (v + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    parent = [[[None] * (v + 1) for _ in range(m + 1)] for _ in range(n + 1)]
    visited = [[[False] * (v + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    dp_vals[0][0][0] = 0
    visited[0][0][0] = True

    queue = [(0, 0, 0)]

    while queue:
        i, j, k = queue.pop(0)
        current_len = dp_vals[i][j][k]

        # Try not including s1[i-1], move s1 forward
        if i > 0:
            if not visited[i-1][j][k]:
                visited[i-1][j][k] = True
                dp_vals[i-1][j][k] = current_len
                parent[i-1][j][k] = (i, j, k)
                queue.append((i-1, j, k))

        # Try not including s2[j-1], move s2 forward
        if j > 0:
            if not visited[i][j-1][k]:
                visited[i][j-1][k] = True
                dp_vals[i][j-1][k] = current_len
                parent[i][j-1][k] = (i, j, k)
                queue.append((i, j-1, k))

        # Try matching s1[i-1] == s2[j-1], move both forward
        if i <= n and j <= m and i > 0 and j > 0 and s1[i-1] == s2[j-1]:
            c = ord(s1[i-1]) - ord('A')
            if k < v and trans[k][c] < v:
                new_k = trans[k][c]
                if not visited[i][j][new_k]:
                    visited[i][j][new_k] = True
                    dp_vals[i][j][new_k] = current_len + 1
                    parent[i][j][new_k] = (i-1, j-1, k)
                    queue.append((i, j, new_k))

    # Find maximum and reconstruct
    max_len = 0
    best_i, best_j, best_k = 0, 0, 0

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v + 1):
                if dp_vals[i][j][k] > max_len:
                    max_len = dp_vals[i][j][k]
                    best_i, best_j, best_k = i, j, k

    if max_len == 0:
        return "0"

    result = []
    i, j, k = best_i, best_j, best_k

    while i > 0 or j > 0:
        p = parent[i][j][k]
        if p is None:
            break

        prev_i, prev_j, prev_k = p

        if i == prev_i + 1 and j == prev_j + 1 and prev_k != k:
            # This transition was a match
            if i - 1 < n:
                result.append(s1[i-1])
            i, j, k = prev_i, prev_j, prev_k
        else:
            i, j, k = prev_i, prev_j, prev_k

    return ''.join(reversed(result))

