def solution(n):
    """
    Find the minimum number of subtractions to reduce a number to zero.
    Each subtraction must use a digit that appears in the current number.
    """
    n = int(n.strip())

    @lru_cache(maxsize=None)
    def min_ops(x):
        if x == 0:
            return 0

        # Get all unique digits in x
        digits = set(int(d) for d in str(x))

        # Find the minimum operations by trying each digit
        return 1 + min(min_ops(x - d) for d in digits)

    result = min_ops(n)
