    visited2 = [False] * (n + 1)
    tin2 = [0] * (n + 1)
    timer2 = 0

    dfs_order = []

    def dfs_order2(u):
        nonlocal timer2
        visited2[u] = True
        timer2 += 1
        dfs_order.append(u)

        for v in adj[u]:
            if not visited2[v]:
                dfs_order2(v)

