    Tries outcomes in order of preference: 3:0, 3:1, 3:2, 0:3, 1:3, 2:3
    """

    def is_valid_set(a_s, b_s):
        """Check if a set score is valid according to volleyball rules"""
        if a_s == b_s:
            return False
        if a_s > b_s:
            return a_s >= 25 and (a_s - b_s >= 2)
        else:
            return b_s >= 25 and (b_s - a_s >= 2)

    def check_sets(valid_sets, target_a, target_b):
        """Check if the sum of points equals the targets"""
        a_sum = sum(s[0] for s in valid_sets)
        b_sum = sum(s[1] for s in valid_sets)
        return a_sum == target_a and b_sum == target_b

    # Try each outcome in order of preference for Team A
    outcomes = ['3:0', '3:1', '3:2', '0:3', '1:3', '2:3']

    for outcome in outcomes:
        awin, bwin = map(int, outcome.split(':'))
        needed_sets = awin + bwin

        sets = []

        # Build sets greedily, trying different valid combinations
        success = False

        # Check if enough points exist for minimum valid sets
        min_points_a = awin * 25 + bwin * 25
        min_points_b = awin * 0 + bwin * 25  # B needs 25 to win each set they win

        if a < min_points_a or b < min_points_b:
            # Try partial sums for the first set
            for a_s in range(25, min(a, 30)):
                for b_s in range(25, min(b, 30)):
