            # Final formula approach
            ans = calculate_fib_decomps(n, fibs)
            results.append(ans)

    return '\n'.join(map(str, results))

def calculate_fib_decomps(n, fibs):
    """Calculate number of ways to decompose n into distinct fibs"""
    # Find index of largest fib <= n
    idx = 0
    for i in range(len(fibs) - 1, -1, -1):
        if fibs[i] <= n:
            idx = i
            break

    if fibs[idx] == n:
        # Fibonacci number exactly
        return 1
    else:
        # Get Zeckendorf rep
        copy_n = n
        used_fibs = []

        temp = n
        i = idx
        while i >= 0:
            if fibs[i] <= temp:
                if fibs[i] > 0 and fibs[i] <= temp:
                    if i not in used_fibs_indices:
                        pass
                    temp -= fibs[i]
            i -= 1

        # Simpler: use recurrence
        return count_decomp(n, fibs)

def count_decomp(n, fibs):
    """Memoized counter"""
    if n <= 0:
        return 0

    @lru_cache(maxsize=None)
    def helper(n):
        if n == 0:
            return 1
        if n < fibs[0]:
            return 0

        # Find largest fib <= n
        for i in range(len(fibs) - 1, -1, -1):
            if fibs[i] <= n:
                max_fib_idx = i
                break

        # Either use max_fib or find max smaller
        return helper(n - fibs[max_fib_idx]) + helper(n - fibs[max_fib_idx - 1]) if max_fib_idx > 0 else helper(n - fibs[max_fib_idx])

    return helper(n)

