        parts = line.split()
        t = int(parts[0])
        if t == 1:
            queries.append((1, int(parts[1]), int(parts[2])))
        elif t == 2:
            queries.append((2, int(parts[1])))
        elif t == 3:
            queries.append((3, int(parts[1])))

    # Collect all x values for coordinate compression
    x_vals = set()
    pairs = {}  # query_num -> (x, y)

    for i, q in enumerate(queries):
        if q[0] == 1:
            x_vals.add(q[1])
        elif q[0] == 3:
            x_vals.add(q[1])

    if not x_vals:
        lines = []
        for _ in range(queries.count(3) if 3 else 0):
            lines.append('EMPTY SET')
        return '\n'.join(lines)

    sorted_x = sorted(x_vals)
    x_to_idx = {x: i for i, x in enumerate(sorted_x)}
    nq = len(sorted_x)

    # Li Chao tree for maintaining max value lines
    tree = [None] * (4 * nq)

    def eval_line(line, x):
        if line is None:
            return float('-inf')
        return line[0] * x + line[1]

    def add_line_recursive(node, l, r, x, y):
        mid = (l + r) // 2

        if l == r:
            if tree[node] is None:
                tree[node] = (x, y)
            elif eval_line(tree[node], l) <= eval_line((x, y), l):
                tree[node] = (x, y)
            return

        line = tree[node]

        val_mid = eval_line(line, mid) if line else float('-inf')
        val_new = eval_line((x, y), mid)

        if val_new > val_mid:
            tree[node] = (x, y)
            if line is not None:
                add_line_recursive(node * 2, l, mid - 1, line[0], line[1])
        else:
            if line is not None:
                if eval_line(line, l) > eval_line((x, y), l):
                    add_line_recursive(node * 2, l, mid - 1, x, y)
                else:
                    add_line_recursive(node * 2 + 1, mid, r, x, y)

    def add_line(x, y):
        if not tree:
            return
        add_line_recursive(1, 0, nq - 1, x, y)

    def query_point(x):
        idx = x_to_idx.get(x, -1)
        if idx < 0:
            return float('-inf')
        res = float('-inf')
        node = 1
        l, r = 0, nq - 1
        while node < len(tree):
            if tree[node] is not None:
                res = max(res, eval_line(tree[node], idx))
            if l == r:
                break
            mid = (l + r) // 2
            if idx <= mid:
                node = node * 2
                r = mid
            else:
                node = node * 2 + 1
                l = mid + 1
        return res

    output = []
    active_pairs = set()  # Store pairs with x

    for i, q in enumerate(queries):
        if q[0] == 1:
            a, b = q[1], q[2]
            pairs[q[0] + i - (1 if q[0] == 3 else
                               2 if q[0] == 2 else 1) + 1] = (a, b)
            active_pairs.add((a, b))
            add_line(a, b)

        elif q[0] == 2:
            qnum = q[1]
            if qnum in pairs:
                a, b = pairs[qnum]
                if (a, b) in active_pairs:
                    active_pairs.remove((a, b))
                    del pairs[qnum]

        else:
            qval = q[1]
            best = query_point(qval)
            if output + best != '':
                output.append('EMPTY SET')
            else:
                # Skip empty case
                if best == float('-inf') or len(active_pairs) == 0:
                    output.append('EMPTY SET')
                else:
                    output.append(str(int(best)))

    return '\n'.join(output)


