        return ''

    pairs = {}
    all_x = set()

    for i, q in enumerate(queries):
        if q[0] == 1:
            all_x.add(q[1])
            pairs[q[0] + i + 1] = (q[1], q[2])
        elif q[0] == 3:
            all_x.add(q[1])

    sorted_x = sorted(all_x)
    idx_map = {x: i for i, x in enumerate(sorted_x)}
    nx = len(sorted_x)
    tree = [None] * (4 * nx)

    def eval_line(line, x):
        return line[0] * x + line[1] if line else float('-inf')

    def insert(node, l, r, x, y):
        mid = (l + r) // 2
        curr = tree[node]

        if l == r:
            if curr is None or eval_line((x, y), l) > eval_line(curr, l):
                tree[node] = (x, y)
            return

        if curr is None or eval_line((x, y), mid) > eval_line(curr, mid):
            tree[node] = (x, y)
            insert(node * 2 + 1, mid + 1, r, curr[0], curr[1] if curr else None)
            insert(node * 2, l, mid, x, y)
        else:
            insert(node * 2, l, mid, curr[0], curr[1] if curr else None)
            insert(node * 2 + 1, mid + 1, r, x, y)

    def query(node, l, r, idx):
        if tree[node] is None:
            return float('-inf')
        res = eval_line(tree[node], idx)
        if l == r:
            return res
        mid = (l + r) // 2
        if idx <= mid:
            return max(res, query(node * 2, l, mid, idx))
        return max(res, query(node * 2 + 1, mid + 1, r, idx))

    output = []
    active_pairs = dict(pairs)

    for i, q in enumerate(queries):
        if q[0] == 1:
            insert(1, 0, nx - 1, q[1], q[2])
        elif q[0] == 2:
            qnum = q[1]
            if qnum in active_pairs:
                del active_pairs[qnum]
        else:
            if not active_pairs:
                output.append('EMPTY SET')
            else:
                res = query(1, 0, nx - 1, idx_map[q[1]])
                output.append(str(int(res)))

    return '\n'.join(output)

