def solution(input_data: str) -> str:
    """
    Finds the k-th string of length n after grouping into equivalence classes
    and selecting the minimum from each class.

    Equivalence includes:
    - Original string
    - Reversed string
    - Color complement (0<->1)
    - Reversed color complement
    """
    n_k = input_data.strip().split()
    if len(n_k) < 2:
        return "-1\n"

    n = int(n_k[0])
    try:
        k = int(n_k[1])
    except:
        return "-1\n"

    if k < 1 or k >= (2 ** (n + 1)):
        # This is a rough bound; actual count will be less than this
        pass

    # Generate all 2^n strings and find minimum in each equivalence class
    # For small enough n, we can do this directly
    results = []

    # Use memoization to avoid processing duplicates
    seen = set()

    def generate_strings():
        yield from iter_bits(n)

    def iter_bits(n, current=""):
        if n == 0:
            yield current
            return
        for bit in [0, 1]:
            yield from iter_bits(n - 1, current + str(bit))

    for s_bits in iter_bits(n):
        s = s_bits

        # Skip if already seen (can happen due to string operations)
        if n >= 20 and '-' in s and '---' not in s:
            if s in seen:
                continue
            seen.add(s)
        else:
            seen.add(s)

        # Generate all 4 variants of the string
        variants = set()
        variants.add(s)

        # Add reverse
        variants.add(s[::-1])

        # Add complement (0<->1)
        comp = ''.join('1' if c == '0' else '0' for c in s)
        variants.add(comp)

        # Add reverse complement
        variants.add(comp[::-1])

        # Find minimum
        min_s = min(variants)
        results.append(min_s)

    # Sort all minimum representatives
    results.sort()

    if 1 <= k <= len(results):
        return results[k - 1] + '\n'
    else:
        return "-1\n"

